      "ar": "قَالَتْ إِحْدَىٰهُمَا يَـٰأَبَتِ اسْتَـءْجِرْهُ إِنَّ خَيْرَ مَنِ اسْتَـءْجَرْتَ الْقَوِيُّ الْأَمِينُ",
